export interface SkillGroup {
  label: string;
  items: string[];
}

export interface Language {
  name: string;
  level: string;
}

export interface Principle {
  title: string;
  text: string;
  /** Optional ordered steps shown under the text */
  steps?: string[];
  /** Slug of a case study that shows this principle in practice */
  caseStudy?: string;
  linkLabel?: string;
}

interface ContactPath {
  title: string;
  text: string;
  /** Email subject, so enquiries are easy to tell apart */
  subject: string;
}

export interface Profile {
  name: string;
  initials: string;
  headline: string;
  /** Shown in the hero; omit to hide */
  availability?: string;
  /** Paragraphs; supports `**bold**` */
  summary: string[];
  /** "How I work" section */
  principles: Principle[];
  /** Contact section, split by audience */
  contact: {
    intro: string;
    hiring: ContactPath;
    project: ContactPath;
  };
  email: string;
  url: string;
  avatarUrl: string;
  location: string;
  githubUrl: string;
  linkedinUrl: string;
  /** Generated by `npm run cv:export` */
  cvUrl: string;
  skills: SkillGroup[];
  languages: Language[];
}
